// Shared schema settings:
//  - JSON output exposes `id` instead of `_id` and hides internal fields
//  - ids are UUID strings, generated by default, so records created offline
//    on a device never collide with records from other devices
const crypto = require('crypto');

const uuid = () => crypto.randomUUID();

function applyJson(schema) {
  schema.set('toJSON', {
    transform: (_doc, ret) => {
      ret.id = ret._id;
      delete ret._id;
      delete ret.__v;
      delete ret.password_hash;
      return ret;
    },
  });
}

module.exports = { uuid, applyJson };
